function Start-WindowsRepair {Show-Header;Write-Host "REPARAR WINDOWS" -ForegroundColor Yellow;Write-Host "Executa DISM RestoreHealth e depois SFC /scannow.";if(-not(Confirm-WinOptimizerAction "Iniciar reparo?")){return};Start-Process dism.exe -ArgumentList "/Online","/Cleanup-Image","/RestoreHealth" -Wait -NoNewWindow;Start-Process sfc.exe -ArgumentList "/scannow" -Wait -NoNewWindow;Write-Status "Reparo finalizado." Green;Save-AppliedChange Manutencao "Reparo Windows" "DISM RestoreHealth e SFC executados.";Pause-WinOptimizer}